// ============================================================================
// 《Pocket Mirror: GoldenerTraum》双层 RPG 状态机设置系统全局控制器 (v2 GPU/SFX 重构版)
// - 动态发现所有 1 级入口 (兼容任意工作区名称与 Token 统计)
// - 两段式流畅转场 (menu -> leaving-menu -> settings / leaving-settings)
// - 内嵌 SE_Cursor / SE_Decision / SE_Buzzer 音效池与静音开关
// - 完整键盘网格导航 (方向键 / WASD / Z / Enter / X / Esc / Q / E)
// - 全控件悬停动态 Help Bar 与响应式 1280x720 缩放
// - 严格注册 ctx.onCleanup，热重载零泄漏，绝不直接覆写 React button.innerText
// ============================================================================
function mountPocketMirrorSettings() {
  if (typeof window === 'undefined' || window.top !== window) return;

  // 若先前热重载遗留控制器，先行彻底清理
  if (typeof window.__PM_SETTINGS_TEARDOWN === 'function') {
    try { window.__PM_SETTINGS_TEARDOWN(); } catch (_) {}
  }

  const ASSET_PROTAGONIST_WALK = "data:image/gif;base64,";
  const ASSET_PROTAGONIST_PORTRAIT = "data:image/webp;base64,";
  const SFX_DATA_URIS = {
    cursor: "data:audio/ogg;base64,",
    decision: "data:audio/ogg;base64,",
    buzzer: "data:audio/ogg;base64,"
  };

  const cleanups = [];
  const registerCleanup = (fn) => {
    if (typeof fn === 'function') cleanups.push(fn);
  };

  function isJrpgEnabled() {
    try {
      if (localStorage.getItem('pm-disable-jrpg-settings') === 'true') return false;
    } catch (_) {}
    if (window.__PM_DISABLE_JRPG_SETTINGS === true) return false;
    try {
      const cfg = window.__AG_PATCH_CTX__?.config;
      if (cfg && cfg.modules && cfg.modules.jrpgSettings === false) return false;
    } catch (_) {}
    return true;
  }

  // --------------------------------------------------------------------------
  // 1. RPG 音效引擎 (预加载池化 Audio + 防抖 + 静音持久化)
  // --------------------------------------------------------------------------
  let sfxMuted = false;
  try {
    sfxMuted = localStorage.getItem('pm-sfx-muted') === '1';
  } catch (_) {}

  const sfxPools = {};
  const sfxCursor = {};
  const sfxLastTs = { cursor: 0, decision: 0, buzzer: 0 };
  const SFX_COOLDOWN = { cursor: 45, decision: 55, buzzer: 65 };
  const SFX_VOLUME = { cursor: 0.28, decision: 0.34, buzzer: 0.32 };

  function ensureAudioPool(kind) {
    if (sfxPools[kind]) return sfxPools[kind];
    const uri = SFX_DATA_URIS[kind];
    if (!uri) return null;
    const pool = [];
    for (let i = 0; i < 3; i++) {
      try {
        const audio = new Audio(uri);
        audio.preload = 'auto';
        audio.volume = SFX_VOLUME[kind] ?? 0.3;
        pool.push(audio);
      } catch (_) {}
    }
    sfxPools[kind] = pool;
    sfxCursor[kind] = 0;
    return pool;
  }

  function playSfx(kind) {
    if (sfxMuted || !isJrpgEnabled()) return;
    const now = performance.now();
    if (now - (sfxLastTs[kind] || 0) < (SFX_COOLDOWN[kind] || 45)) return;
    sfxLastTs[kind] = now;
    try {
      const pool = ensureAudioPool(kind);
      if (!pool || pool.length === 0) return;
      const idx = (sfxCursor[kind] || 0) % pool.length;
      sfxCursor[kind] = idx + 1;
      const a = pool[idx];
      a.currentTime = 0;
      const p = a.play();
      if (p && typeof p.catch === 'function') p.catch(() => {});
    } catch (_) {}
  }

  // 延迟预热，避免阻塞首帧渲染
  const warmTimer = setTimeout(() => {
    if (isJrpgEnabled()) {
      ensureAudioPool('cursor');
      ensureAudioPool('decision');
      ensureAudioPool('buzzer');
    }
  }, 600);
  registerCleanup(() => clearTimeout(warmTimer));

  // --------------------------------------------------------------------------
  // 2. React 安全的双语控制器 (共享 window.__ag_orig_text_map，仅操作纯 Text 节点)
  // --------------------------------------------------------------------------
  const EXCLUDE_I18N_SEL = 'code, pre, kbd, script, style, textarea, input, select, [contenteditable], .monaco-editor, .xterm, #pm-sound-btn, .pm-no-i18n, [data-pm-no-i18n="1"]';
  const NAV_LABELS_ZH = {
    'General': '常规',
    'App': '应用',
    'Appearance': '外观',
    'Shortcuts': '快捷键',
    'Notifications': '通知',
    'Models': '模型',
    'Browser': '浏览器',
    'Conversations': '会话',
    'Account': '账号',
    'Billing': '账单',
    'Extensions': '扩展',
    'MCP': 'MCP 工具',
    'Rules': '规则',
    'Indexing': '索引',
    'Security': '安全',
    'Privacy': '隐私',
    'Token Analytics': 'Token 统计',
    'Token 统计': 'Token 统计'
  };

  const TAB_HELP_ZH = {
    'General': '配置界面布局模式、编辑器行为与常规全局偏好。',
    'App': '管理应用更新、遥测隐私、实验室功能与终端启动选项。',
    'Appearance': '切换《Pocket Mirror》配色预设、字体、排版密度与视觉效果。',
    'Shortcuts': '浏览或检索 Antigravity 全局快捷键组合。',
    'Notifications': '控制桌面通知、声音提示与代理任务完成提醒。',
    'Models': '查看与管理云端大语言模型配额、默认模型与推理参数。',
    'Browser': '配置内置浏览器视图、权限策略与自动交互沙箱。',
    'Conversations': '管理历史对话存储、压缩策略与工作区上下文保留。',
    'Account': '查看当前登录账号、订阅计划与本地连接状态。',
    'Token Analytics': '审计近期会话 Token 消耗分布、费用估算与配额预警。'
  };

  const TAB_HELP_EN = {
    'General': 'Configure workspace layout modes, editor behavior, and core defaults.',
    'App': 'Manage updates, startup behavior, terminal integration, and lab features.',
    'Appearance': 'Customize Pocket Mirror themes, typography, dark presets, and density.',
    'Shortcuts': 'Browse and search global Antigravity keyboard shortcuts.',
    'Notifications': 'Control desktop alerts, completion chimes, and agent status badges.',
    'Models': 'Inspect active model quotas, routing defaults, and context limits.',
    'Browser': 'Configure built-in webview origin policies and browser automation.',
    'Conversations': 'Manage chat history persistence, compaction, and context preferences.',
    'Account': 'Inspect active profile, subscription tier, and credential health.',
    'Token Analytics': 'Audit token usage breakdowns, model quotas, and budget trends.'
  };

  let curLang = 'zh';
  try {
    const saved = localStorage.getItem('pm-lang-mode');
    if (saved === 'en' || saved === 'zh') curLang = saved;
  } catch (_) {}

  let applyInProgress = false;

  function applySafeTextLanguage(targetRoot, lang) {
    if (!targetRoot || applyInProgress) return;
    applyInProgress = true;
    try {
      const dict = window.__ag_i18n_dict;
      if (!window.__ag_orig_text_map) window.__ag_orig_text_map = new WeakMap();
      const origMap = window.__ag_orig_text_map;
      const isZh = lang === 'zh';

      const walker = document.createTreeWalker(targetRoot, NodeFilter.SHOW_TEXT, {
        acceptNode(node) {
          const val = node.nodeValue;
          if (!val || !val.trim()) return NodeFilter.FILTER_REJECT;
          const parent = node.parentElement;
          if (!parent || parent.closest(EXCLUDE_I18N_SEL)) return NodeFilter.FILTER_REJECT;
          return NodeFilter.FILTER_ACCEPT;
        }
      });

      const nodes = [];
      let n;
      while ((n = walker.nextNode())) nodes.push(n);

      for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];
        const raw = node.nodeValue;
        const rec = origMap.get(node);

        if (!isZh) {
          // 恢复英文原文
          if (rec && raw === rec.lastVal && rec.origRaw !== raw) {
            node.nodeValue = rec.origRaw;
          }
          continue;
        }

        if (!dict) continue;
        const trimmed = raw.trim();
        let trans = dict[trimmed] || (trimmed === 'Loading token usage...' ? '正在统计 Token 占用...' : undefined);
        if (!trans && trimmed.endsWith(':') && dict[trimmed.slice(0, -1)]) {
          trans = dict[trimmed.slice(0, -1)] + '：';
        }
        if (trans && trans !== trimmed) {
          const leading = raw.match(/^\s*/)[0];
          const trailing = raw.match(/\s*$/)[0];
          const nextVal = leading + trans + trailing;
          if (raw !== nextVal) {
            if (!rec) {
              origMap.set(node, { origRaw: raw, lastVal: nextVal, ver: 2 });
            } else {
              rec.lastVal = nextVal;
            }
            node.nodeValue = nextVal;
          }
        }
      }

      // 仅更新按钮内部已有 Text 节点，绝不重写 button.innerText 破坏 React Fiber 子树
      const navButtons = targetRoot.querySelectorAll('[data-testid^="settings-nav-item-"], #ag-token-nav-btn');
      navButtons.forEach((btn) => {
        const key = (btn.getAttribute('data-testid') || '').replace('settings-nav-item-', '') || (btn.id === 'ag-token-nav-btn' ? 'Token Analytics' : '');
        if (!key) return;
        const targetLabel = isZh ? (NAV_LABELS_ZH[key] || dict?.[key] || key) : key;
        const tw = document.createTreeWalker(btn, NodeFilter.SHOW_TEXT);
        const tNodes = [];
        let tn;
        while ((tn = tw.nextNode())) {
          if (tn.nodeValue && tn.nodeValue.trim()) tNodes.push(tn);
        }
        if (tNodes.length > 0) {
          const first = tNodes[0];
          if (!origMap.get(first)) origMap.set(first, { origRaw: first.nodeValue, lastVal: targetLabel, ver: 2 });
          if (first.nodeValue.trim() !== targetLabel) {
            first.nodeValue = targetLabel;
            const r = origMap.get(first);
            if (r) r.lastVal = targetLabel;
          }
        }
      });
    } finally {
      applyInProgress = false;
    }
  }

  function syncLangUI(lang) {
    curLang = lang === 'en' ? 'en' : 'zh';
    try { localStorage.setItem('pm-lang-mode', curLang); } catch (_) {}
    const isZh = curLang === 'zh';

    document.querySelectorAll('.pm-lang-btn, .pm-quick-lang-btn, .pm-header-lang-btn').forEach((el) => {
      el.classList.toggle('active', el.getAttribute('data-lang') === curLang);
    });

    document.querySelectorAll('.settings-modal-container').forEach((c) => {
      const exitBtn = c.querySelector(':scope > button:first-child');
      if (exitBtn) exitBtn.setAttribute('data-pm-exit-label', isZh ? 'X 退出' : 'X Exit');
      const retBtn = c.querySelector('#pm-return-btn');
      if (retBtn) retBtn.textContent = isZh ? 'X 返回' : 'X Back';
      const hints = c.querySelector('#pm-key-hints');
      if (hints) {
        hints.textContent = isZh
          ? '[↑↓←→/WASD] 移动 · [Q/E] 切换标签 · [X/Esc] 返回主菜单'
          : '[Arrows/WASD] Move · [Q/E] Switch Tab · [X/Esc] Back';
      }
      const soundBtn = c.querySelector('#pm-sound-btn');
      if (soundBtn) updateSoundButton(soundBtn);
      const cornerHints = c.querySelector('.pm-decor-corner-hints');
      if (cornerHints) {
        cornerHints.textContent = isZh
          ? '[↑↓←→ / WASD] 移动 · [Z / Enter] 进入 · [X / Esc] 关闭'
          : '[Arrows / WASD] Move · [Z / Enter] Enter · [X / Esc] Close';
      }
      const timeLabel = c.querySelector('#pm-hud-time-label');
      if (timeLabel) timeLabel.textContent = isZh ? '时间' : 'TIME';
      const chapLabel = c.querySelector('#pm-hud-chapter-label');
      if (chapLabel) chapLabel.textContent = isZh ? '章节' : 'CHAPTERS';
      applySafeTextLanguage(c, curLang);
    });
  }

  window.__pmLang = {
    get: () => curLang,
    set: (lang) => syncLangUI(lang),
    reapply: () => syncLangUI(curLang)
  };

  function updateSoundButton(btn) {
    if (!btn) return;
    btn.setAttribute('data-muted', sfxMuted ? 'true' : 'false');
    const isZh = curLang === 'zh';
    btn.textContent = sfxMuted
      ? (isZh ? '🔇 静音' : '🔇 Muted')
      : (isZh ? '🔊 音效' : '🔊 SFX');
    btn.title = isZh ? '切换游戏音效 (Cursor / Decision / Buzzer)' : 'Toggle RPG Sound Effects';
  }

  // --------------------------------------------------------------------------
  // 3. 动态 1 级入口收集与网格行数自适应 + 响应式 stage scale
  // --------------------------------------------------------------------------
  function getNavButtons(container) {
    if (!container) return [];
    const sidebar = container.querySelector('[data-testid="settings-sidebar"]');
    if (!sidebar) return [];
    return Array.from(sidebar.querySelectorAll('button[data-testid^="settings-nav-item-"], #ag-token-nav-btn'));
  }

  function getActiveNavButton(container) {
    const isToken = container.getAttribute('data-ag-token-tab-active') === '1';
    if (isToken) {
      const tok = container.querySelector('#ag-token-nav-btn[data-active="1"], #ag-token-nav-btn');
      if (tok) return tok;
    }
    const navs = getNavButtons(container);
    return navs.find((b) =>
      b.classList.contains('bg-sidebar-secondary') ||
      b.classList.contains('bg-accent') ||
      b.getAttribute('aria-current') === 'page' ||
      b.getAttribute('data-state') === 'active'
    ) || navs[0] || null;
  }

  function getNavRawKey(btn) {
    if (!btn) return '';
    if (btn.id === 'ag-token-nav-btn') return 'Token Analytics';
    return (btn.getAttribute('data-testid') || '').replace('settings-nav-item-', '') || (btn.textContent || '').trim();
  }

  function updateStageScale(container) {
    if (!container) return;
    const w = window.innerWidth || 1280;
    const h = window.innerHeight || 720;
    const scale = Math.max(0.55, Math.min((w - 32) / 1280, (h - 36) / 720, 1));
    container.style.setProperty('--pm-stage-scale', scale.toFixed(4));
  }

  let resizeRaf = 0;
  const onResize = () => {
    if (resizeRaf) return;
    resizeRaf = requestAnimationFrame(() => {
      resizeRaf = 0;
      document.querySelectorAll('.settings-modal-container[data-pm-settings="enabled"]').forEach(updateStageScale);
    });
  };
  window.addEventListener('resize', onResize, { passive: true });
  registerCleanup(() => {
    window.removeEventListener('resize', onResize);
    if (resizeRaf) cancelAnimationFrame(resizeRaf);
  });

  // --------------------------------------------------------------------------
  // 4. 会话计时与少女陪伴 HUD 刷新
  // --------------------------------------------------------------------------
  if (!window.__pmSessionStartMs) {
    window.__pmSessionStartMs = Date.now();
  }

  function formatElapsed(ms) {
    const total = Math.max(0, Math.floor(ms / 1000));
    const hh = String(Math.floor(total / 3600)).padStart(2, '0');
    const mm = String(Math.floor((total % 3600) / 60)).padStart(2, '0');
    const ss = String(total % 60).padStart(2, '0');
    return `${hh}:${mm}:${ss}`;
  }

  function updateClocksAndStats() {
    const elapsed = formatElapsed(Date.now() - (window.__pmSessionStartMs || Date.now()));
    document.querySelectorAll('.pm-decor-clock-val').forEach((el) => {
      if (el.textContent !== elapsed) el.textContent = elapsed;
    });
  }

  const clockTimer = setInterval(updateClocksAndStats, 1000);
  registerCleanup(() => clearInterval(clockTimer));

  // --------------------------------------------------------------------------
  // 5. 状态机转场协调器 (menu <-> leaving-menu <-> settings <-> leaving-settings -> closing)
  // --------------------------------------------------------------------------
  let sceneTimers = new WeakMap();
  let tabSwitchTimers = new WeakMap();
  let bypassCloseIntercept = false;

  function clearSceneTimer(container) {
    const t = sceneTimers.get(container);
    if (t) {
      clearTimeout(t);
      sceneTimers.delete(container);
    }
  }

  function centerTabInRail(rail, tabBtn) {
    if (!rail || !tabBtn) return;
    const rr = rail.getBoundingClientRect();
    const tr = tabBtn.getBoundingClientRect();
    if (!rr.width || !tr.width) return;
    const delta = (tr.left + tr.width / 2) - (rr.left + rr.width / 2);
    rail.scrollLeft = Math.max(0, rail.scrollLeft + delta);
  }

  function enterSceneSettings(container, clickedBtn) {
    const scene = container.getAttribute('data-pm-scene') || 'menu';
    if (scene === 'closing' || container.getAttribute('data-pm-closing') === '1') return;

    if (scene === 'settings') {
      // 二级内部切页签：零闪烁轻淡入 + 轨道立刻居中 + 滚回顶部
      container.setAttribute('data-pm-tab-switching', '1');
      const prev = tabSwitchTimers.get(container);
      if (prev) clearTimeout(prev);
      tabSwitchTimers.set(container, setTimeout(() => {
        if (container.isConnected) container.removeAttribute('data-pm-tab-switching');
      }, 170));

      requestAnimationFrame(() => {
        const rail = container.querySelector('[data-testid="settings-sidebar"]');
        if (clickedBtn && clickedBtn.isConnected) centerTabInRail(rail, clickedBtn);
        const vp = container.querySelector('[data-ag-token-tab-active="1"] #ag-token-analytics-panel, [data-ag-native-settings-scroll="1"], .w-full.bg-transparent.h-full.overflow-y-auto');
        if (vp) vp.scrollTop = 0;
        syncHelpForTab(container, clickedBtn || getActiveNavButton(container));
      });
      return;
    }

    // 一级 -> leaving-menu (115ms) -> settings
    clearSceneTimer(container);
    container.setAttribute('data-pm-scene', 'leaving-menu');
    container.removeAttribute('data-active-detail');
    sceneTimers.set(container, setTimeout(() => {
      if (!container.isConnected || container.getAttribute('data-pm-closing') === '1') return;
      container.setAttribute('data-pm-scene', 'settings');
      container.setAttribute('data-active-detail', 'true');
      requestAnimationFrame(() => {
        const active = clickedBtn && clickedBtn.isConnected ? clickedBtn : getActiveNavButton(container);
        const rail = container.querySelector('[data-testid="settings-sidebar"]');
        if (active) centerTabInRail(rail, active);
        syncHelpForTab(container, active);
        ensureLanguageCard(container);
        applySafeTextLanguage(container, curLang);
      });
    }, 115));
  }

  function returnToSceneMenu(container) {
    const scene = container.getAttribute('data-pm-scene');
    if (scene !== 'settings' && scene !== 'leaving-menu') return;
    clearSceneTimer(container);
    playSfx('buzzer');
    container.setAttribute('data-pm-scene', 'leaving-settings');
    sceneTimers.set(container, setTimeout(() => {
      if (!container.isConnected || container.getAttribute('data-pm-closing') === '1') return;
      container.setAttribute('data-pm-scene', 'menu');
      container.removeAttribute('data-active-detail');
      const active = getActiveNavButton(container);
      syncKbdSelection(container, active);
    }, 125));
  }

  function closeSettingsModalSmoothly(container, backdrop, nativeCloseBtn) {
    if (!container || container.getAttribute('data-pm-closing') === '1') return;
    clearSceneTimer(container);
    container.setAttribute('data-pm-closing', '1');
    container.setAttribute('data-pm-scene', 'closing');
    container.setAttribute('data-modal-closing', 'true');
    if (backdrop) backdrop.setAttribute('data-modal-closing', 'true');
    playSfx('buzzer');

    setTimeout(() => {
      bypassCloseIntercept = true;
      try {
        if (nativeCloseBtn && nativeCloseBtn.isConnected) {
          nativeCloseBtn.click();
        } else if (backdrop && backdrop.isConnected) {
          backdrop.click();
        } else {
          window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true, cancelable: true }));
        }
      } finally {
        bypassCloseIntercept = false;
      }
      setTimeout(() => {
        if (container.isConnected) {
          container.removeAttribute('data-pm-closing');
          container.removeAttribute('data-modal-closing');
          if (backdrop && backdrop.isConnected) backdrop.removeAttribute('data-modal-closing');
        }
      }, 450);
    }, 135);
  }

  // --------------------------------------------------------------------------
  // 6. 键盘导航光标控制与动态底部 Help Bar
  // --------------------------------------------------------------------------
  const menuIndexMap = new WeakMap();

  function syncKbdSelection(container, targetBtn) {
    const btns = getNavButtons(container);
    btns.forEach((b) => b.classList.remove('pm-kbd-active'));
    if (!btns.length) return;
    const idx = targetBtn ? Math.max(0, btns.indexOf(targetBtn)) : Math.min(menuIndexMap.get(container) || 0, btns.length - 1);
    menuIndexMap.set(container, idx);
    if (btns[idx]) btns[idx].classList.add('pm-kbd-active');
  }

  function syncHelpForTab(container, tabBtn) {
    const bar = container?.querySelector('#pm-help-bar');
    if (!bar) return;
    const key = getNavRawKey(tabBtn);
    const isZh = curLang === 'zh';
    const text = isZh
      ? (TAB_HELP_ZH[key] || `${key} — 浏览与调整当前章节系统设定。`)
      : (TAB_HELP_EN[key] || `Configure ${key} settings and preferences.`);
    if (bar.getAttribute('data-last-help') !== text) {
      bar.setAttribute('data-last-help', text);
      bar.textContent = text;
    }
  }

  function extractControlHelpText(container, el) {
    if (!el || !el.closest) return null;
    const isZh = curLang === 'zh';

    if (el.id === 'pm-return-btn') return isZh ? '返回《Pocket Mirror》主菜单章节目录 (X / Esc)' : 'Return to Pocket Mirror Command Menu (X / Esc)';
    if (el.id === 'pm-sound-btn') return isZh ? '开启或静音 RPG 交互音效 (Cursor / Decision / Buzzer)' : 'Toggle Pocket Mirror RPG sound effects';
    if (el.id === 'pm-tab-prev' || el.id === 'pm-tab-next') return isZh ? '左右滚动顶部章节页签栏 (快捷键 Q / E)' : 'Scroll category tabs horizontally (Shortcuts: Q / E)';

    const navBtn = el.closest('[data-testid="settings-sidebar"] :is(button[data-testid^="settings-nav-item-"], #ag-token-nav-btn)');
    if (navBtn) {
      const k = getNavRawKey(navBtn);
      return isZh ? (TAB_HELP_ZH[k] || `${navBtn.textContent.trim()} — 章节设置`) : (TAB_HELP_EN[k] || `Open ${k} settings`);
    }

    const radio = el.closest('#project4kMode [role="radio"]');
    if (radio) {
      const t = radio.querySelector('span')?.textContent?.trim() || '';
      const d = radio.querySelector('p')?.textContent?.trim() || '';
      return d ? `${t}：${d}` : t;
    }

    const warmBtn = el.closest('button[data-ag-warm-night-btn="1"]');
    if (warmBtn) return isZh ? '切换暖夜护眼色调预设，柔和对比度保护夜间视力。' : 'Toggle Warm Night eye-care dark preset.';

    const ctrl = el.closest('button[role="switch"], button[role="checkbox"], [data-slot="slider"], [data-slot="toggle-group"], button[role="combobox"], select, input, kbd, .agy-card button');
    if (ctrl) {
      const row = ctrl.closest('.agy-card > div, .space-y-4 > div, [class*="justify-between"]') || ctrl.parentElement;
      if (row) {
        const desc = row.querySelector('.text-muted-foreground, p')?.textContent?.trim();
        const title = row.querySelector('.text-foreground, label, .font-medium, span')?.textContent?.trim();
        if (desc && desc.length > 3 && desc.length <= 92) return desc;
        if (title && title.length > 1) return title;
      }
      const label = ctrl.getAttribute('aria-label') || ctrl.textContent?.trim();
      if (label) return label.slice(0, 88);
    }
    return null;
  }

  // --------------------------------------------------------------------------
  // 7. DOM 注入与事件绑定（严守不重排 React 原生容器）
  // --------------------------------------------------------------------------
  let lastHoveredInteractive = null;

  function buildProfileNameText() {
    try {
      const saved = localStorage.getItem('pm-profile-name');
      if (saved && saved.trim()) {
        const val = saved.trim();
        // 过滤旧缓存中残留的剧透真名 (Base64 校验，确保源码 0 剧透词汇)
        const b64 = btoa(unescape(encodeURIComponent(val.toLowerCase())));
        if (b64 !== 'Z29sZGlh' && b64 !== '5oiI5bCU6L+q5Lqa') {
          return val;
        }
      }
    } catch (_) {}
    return curLang === 'zh' ? '少女' : 'The Girl';
  }

  function detectPresetSubtitle() {
    try {
      const ctx = window.__AG_PATCH_CTX__;
      const preset = ctx?.darkPreset || ctx?.preset || 'onyx';
      return `Theme · ${preset}`;
    } catch (_) {
      return 'Goldenertraum';
    }
  }

  function injectModalDecor(container) {
    if (!container || container.getAttribute('data-pm-injected') === '1') return;
    container.setAttribute('data-pm-injected', '1');
    container.setAttribute('data-pm-settings', 'enabled');
    container.setAttribute('data-pm-scene', 'menu');
    container.removeAttribute('data-active-detail');
    const exitEl = container.querySelector(':scope > button:first-child');
    if (exitEl) exitEl.setAttribute('data-pm-exit-label', curLang === 'zh' ? 'X 退出' : 'X Exit');

    updateStageScale(container);

    // A. 镜之少女主菜单装饰层 (#pm-char-decor-layer)
    if (!container.querySelector('#pm-char-decor-layer')) {
      const decor = document.createElement('div');
      decor.id = 'pm-char-decor-layer';
      decor.style.cssText = 'position:absolute; inset:0; pointer-events:none; z-index:28;';

      const savedName = buildProfileNameText();
      const presetSub = detectPresetSubtitle();
      const navCount = getNavButtons(container).length;
      const elapsed = formatElapsed(Date.now() - (window.__pmSessionStartMs || Date.now()));

      decor.innerHTML = `
        <div class="pm-decor-crown-walker" style="position:absolute; top:56px; left:50%; transform:translate3d(-50%,0,0); width:62px; height:62px; display:flex; align-items:center; justify-content:center;">
          <img src="${ASSET_PROTAGONIST_WALK}" alt="Protagonist Sprite" style="width:52px; height:52px; object-fit:contain; image-rendering:pixelated;" />
        </div>
        <div class="pm-decor-portrait" style="position:absolute; right:184px; bottom:94px; width:204px; height:266px; background-image:url('${ASSET_PROTAGONIST_PORTRAIT}'); background-size:contain; background-repeat:no-repeat; background-position:right bottom;"></div>
        <div class="pm-decor-hud" style="position:absolute; right:254px; top:184px; text-align:right; color:#f7eecf; font-family:'Cinzel','Noto Serif SC',serif; pointer-events:auto;">
          <div style="display:inline-flex; align-items:center; gap:6px; justify-content:flex-end;">
            <span id="pm-hud-name" title="Click to rename" style="font-size:29px; font-weight:700; color:#ffd885; letter-spacing:2px; cursor:pointer; text-shadow:0 2px 6px rgba(0,0,0,0.95);">${savedName}</span>
            <button type="button" id="pm-hud-rename-btn" class="pm-quick-lang-btn pm-no-i18n" title="Rename" style="padding:1px 6px; font-size:11px;">✎</button>
          </div>
          <div style="font-size:13px; color:#d8b878; letter-spacing:1.4px; margin-top:2px;">LV 99 · <span class="pm-no-i18n">${presetSub}</span></div>
          <div style="width:176px; height:8px; background:rgba(0,0,0,0.68); border:1px solid #d4af37; border-radius:4px; margin:7px 0 3px auto; overflow:hidden;">
            <div style="width:100%; height:100%; background:linear-gradient(90deg, #b80f38, #e63956, #ff6b81);"></div>
          </div>
          <div style="font-size:12px; color:#f4e3b8; font-family:'JetBrains Mono',monospace;">HP 354 / 354</div>
          <div style="margin-top:8px; display:inline-flex; gap:5px; align-items:center; background:rgba(20,10,20,0.75); border:1px solid rgba(212,175,55,0.4); border-radius:5px; padding:3px 7px;">
            <button type="button" class="pm-quick-lang-btn pm-no-i18n ${curLang === 'zh' ? 'active' : ''}" data-lang="zh">中文</button>
            <button type="button" class="pm-quick-lang-btn pm-no-i18n ${curLang === 'en' ? 'active' : ''}" data-lang="en">EN</button>
          </div>
        </div>
        <div class="pm-decor-corner-hints pm-no-i18n" style="position:absolute; top:26px; left:68px; font-family:'Cinzel','Noto Serif SC',serif; font-size:12px; color:#b8a58e; text-shadow:0 1px 3px #000; letter-spacing:0.6px;">
          [↑↓←→ / WASD] 移动 · [Z / Enter] 进入 · [X / Esc] 关闭
        </div>
        <div class="pm-decor-bottom-stats pm-no-i18n" style="position:absolute; bottom:18px; left:240px; right:240px; display:flex; justify-content:space-between; align-items:center; font-family:'Cinzel','Noto Serif SC',serif; font-size:15px; color:#dfceb0; text-shadow:0 2px 4px #000; letter-spacing:1.2px;">
          <span><em id="pm-hud-time-label" style="font-style:normal;">${curLang === 'zh' ? '时间' : 'TIME'}</em> <strong class="pm-decor-clock-val" style="color:#ffffff; margin-left:6px; font-family:'JetBrains Mono',monospace;">${elapsed}</strong></span>
          <span><em id="pm-hud-chapter-label" style="font-style:normal;">${curLang === 'zh' ? '章节' : 'CHAPTERS'}</em> <strong id="pm-chapter-count" style="color:#ffd885; margin-left:6px;">${navCount || 9} Chapters</strong></span>
        </div>
      `;
      container.appendChild(decor);

      // 快速语言切换按钮点击
      decor.querySelectorAll('.pm-quick-lang-btn').forEach((btn) => {
        btn.addEventListener('click', (ev) => {
          ev.stopPropagation();
          playSfx('decision');
          syncLangUI(btn.getAttribute('data-lang'));
        });
      });

      // 角色名称编辑交互
      const nameSpan = decor.querySelector('#pm-hud-name');
      const renameBtn = decor.querySelector('#pm-hud-rename-btn');
      const startRename = (ev) => {
        ev.stopPropagation();
        const cur = nameSpan.textContent.trim();
        const input = document.createElement('input');
        input.type = 'text';
        input.value = cur;
        input.maxLength = 18;
        input.style.cssText = 'width:150px; padding:2px 6px; font-size:18px; text-align:right; color:#ffd885; background:rgba(16,8,20,0.95); border:1px solid #ffd885; border-radius:4px; outline:none;';
        nameSpan.replaceWith(input);
        input.focus();
        input.select();
        const commit = () => {
          const next = input.value.trim() || (curLang === 'zh' ? '少女' : 'The Girl');
          nameSpan.textContent = next;
          try { localStorage.setItem('pm-profile-name', next); } catch (_) {}
          if (input.isConnected) input.replaceWith(nameSpan);
          playSfx('decision');
        };
        input.addEventListener('blur', commit, { once: true });
        input.addEventListener('keydown', (ke) => {
          ke.stopPropagation();
          if (ke.key === 'Enter') { ke.preventDefault(); commit(); }
          if (ke.key === 'Escape') {
            ke.preventDefault();
            if (input.isConnected) input.replaceWith(nameSpan);
            playSfx('buzzer');
          }
        });
      };
      if (nameSpan && renameBtn) {
        nameSpan.addEventListener('dblclick', startRename);
        renameBtn.addEventListener('click', startRename);
      }
    }

    // B. 二级内部纯绒布背衬 + 相框 + 返回键 + 音效键 + 左右箭头 + 动态 Help Bar
    if (!container.querySelector('#pm-options-bg')) {
      const bg = document.createElement('div');
      bg.id = 'pm-options-bg';
      container.appendChild(bg);
    }

    if (!container.querySelector('#pm-options-frame')) {
      const f = document.createElement('div');
      f.id = 'pm-options-frame';
      container.appendChild(f);
    }

    if (!container.querySelector('#pm-sound-btn')) {
      const sBtn = document.createElement('button');
      sBtn.id = 'pm-sound-btn';
      sBtn.type = 'button';
      sBtn.className = 'pm-hud-btn pm-no-i18n';
      updateSoundButton(sBtn);
      sBtn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        sfxMuted = !sfxMuted;
        try { localStorage.setItem('pm-sfx-muted', sfxMuted ? '1' : '0'); } catch (_) {}
        updateSoundButton(sBtn);
        if (!sfxMuted) playSfx('decision');
      });
      container.appendChild(sBtn);
    }

    if (!container.querySelector('#pm-return-btn')) {
      const rBtn = document.createElement('button');
      rBtn.id = 'pm-return-btn';
      rBtn.type = 'button';
      rBtn.className = 'pm-hud-btn pm-no-i18n';
      rBtn.textContent = curLang === 'zh' ? 'X 返回' : 'X Back';
      rBtn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        returnToSceneMenu(container);
      });
      container.appendChild(rBtn);
    }

    if (!container.querySelector('#pm-key-hints')) {
      const kh = document.createElement('div');
      kh.id = 'pm-key-hints';
      kh.className = 'pm-no-i18n';
      kh.textContent = curLang === 'zh'
        ? '[↑↓←→/WASD] 移动 · [Q/E] 切换标签 · [X/Esc] 返回主菜单'
        : '[Arrows/WASD] Move · [Q/E] Switch Tab · [X/Esc] Back';
      container.appendChild(kh);
    }

    if (!container.querySelector('#pm-tab-prev')) {
      const prevBtn = document.createElement('button');
      prevBtn.id = 'pm-tab-prev';
      prevBtn.type = 'button';
      prevBtn.className = 'pm-tab-arrow pm-hud-btn pm-no-i18n';
      prevBtn.textContent = '◀';
      prevBtn.title = 'Scroll tabs left';
      prevBtn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        const rail = container.querySelector('[data-testid="settings-sidebar"]');
        if (rail) rail.scrollBy({ left: -210, behavior: 'smooth' });
        playSfx('cursor');
      });
      container.appendChild(prevBtn);
    }

    if (!container.querySelector('#pm-tab-next')) {
      const nextBtn = document.createElement('button');
      nextBtn.id = 'pm-tab-next';
      nextBtn.type = 'button';
      nextBtn.className = 'pm-tab-arrow pm-hud-btn pm-no-i18n';
      nextBtn.textContent = '▶';
      nextBtn.title = 'Scroll tabs right';
      nextBtn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        const rail = container.querySelector('[data-testid="settings-sidebar"]');
        if (rail) rail.scrollBy({ left: 210, behavior: 'smooth' });
        playSfx('cursor');
      });
      container.appendChild(nextBtn);
    }

    if (!container.querySelector('#pm-help-bar')) {
      const help = document.createElement('div');
      help.id = 'pm-help-bar';
      help.className = 'pm-no-i18n';
      container.appendChild(help);
      syncHelpForTab(container, getActiveNavButton(container));
    }

    // C. 容器级事件委托 (Zero Per-Node Leaks) — 直接绑定在 [data-testid="settings-sidebar"] 轨道
    const railEl = container.querySelector('[data-testid="settings-sidebar"]');
    if (railEl && !railEl.dataset.pmWheelBound) {
      railEl.dataset.pmWheelBound = '1';
      railEl.addEventListener('wheel', (we) => {
        if (container.getAttribute('data-pm-scene') === 'settings' && Math.abs(we.deltaY) > Math.abs(we.deltaX)) {
          railEl.scrollLeft += we.deltaY * 0.75;
          we.preventDefault();
        }
      }, { passive: false });
    }

    // 拦截原生右上角关闭按钮，播放磁吸退场后关闭
    const nativeClose = container.querySelector(':scope > button:first-child');
    if (nativeClose && !nativeClose.dataset.pmCloseBound) {
      nativeClose.dataset.pmCloseBound = '1';
      nativeClose.addEventListener('click', (ev) => {
        if (bypassCloseIntercept) return;
        ev.preventDefault();
        ev.stopPropagation();
        const backdrop = document.querySelector('.settings-modal-backdrop');
        closeSettingsModalSmoothly(container, backdrop, nativeClose);
      }, true);
    }

    // 容器内统一委托 click / pointerover / focusin (仅触发一次捕获清理)
    if (!container.dataset.pmEventsBound) {
      container.dataset.pmEventsBound = '1';

      container.addEventListener('click', (ev) => {
        const navBtn = ev.target.closest?.('[data-testid="settings-sidebar"] :is(button[data-testid^="settings-nav-item-"], #ag-token-nav-btn)');
        if (navBtn) {
          playSfx('decision');
          syncKbdSelection(container, navBtn);
          enterSceneSettings(container, navBtn);
          return;
        }
        const ctrl = ev.target.closest?.('button[role="switch"], button[role="checkbox"], [role="radio"], [role="combobox"], select, [data-slot="toggle-group"] button, button.bg-primary, .agy-card button');
        if (ctrl && container.getAttribute('data-pm-scene') === 'settings') {
          if (ctrl.closest('#project4kMode') || ctrl.classList.contains('bg-primary')) {
            playSfx('decision');
          } else {
            playSfx('cursor');
          }
        }
      }, true);

      container.addEventListener('pointerover', (ev) => {
        const interactive = ev.target.closest?.('[data-testid="settings-sidebar"] :is(button[data-testid^="settings-nav-item-"], #ag-token-nav-btn), #project4kMode [role="radio"], button[role="switch"], button[role="checkbox"], [data-slot="toggle-group"] button, button[role="combobox"], select, .agy-card button, #pm-return-btn, #pm-sound-btn, .pm-tab-arrow');
        if (interactive && interactive !== lastHoveredInteractive) {
          lastHoveredInteractive = interactive;
          playSfx('cursor');
          if (interactive.matches('[data-testid="settings-sidebar"] :is(button[data-testid^="settings-nav-item-"], #ag-token-nav-btn)') && container.getAttribute('data-pm-scene') === 'menu') {
            syncKbdSelection(container, interactive);
          }
        } else if (!interactive) {
          lastHoveredInteractive = null;
        }

        if (container.getAttribute('data-pm-scene') === 'settings') {
          const helpMsg = extractControlHelpText(container, ev.target);
          if (helpMsg) {
            const bar = container.querySelector('#pm-help-bar');
            if (bar && bar.getAttribute('data-last-help') !== helpMsg) {
              bar.setAttribute('data-last-help', helpMsg);
              bar.textContent = helpMsg;
            }
          }
        }
      }, { passive: true });

      container.addEventListener('focusin', (ev) => {
        if (container.getAttribute('data-pm-scene') === 'settings') {
          const helpMsg = extractControlHelpText(container, ev.target);
          if (helpMsg) {
            const bar = container.querySelector('#pm-help-bar');
            if (bar && bar.getAttribute('data-last-help') !== helpMsg) {
              bar.setAttribute('data-last-help', helpMsg);
              bar.textContent = helpMsg;
            }
          }
        }
      }, { passive: true });
    }
  }

  // --------------------------------------------------------------------------
  // 8. 外观页签内嵌双语设置卡 (保留原有交互并在 Appearance 页自动挂入)
  // --------------------------------------------------------------------------
  function ensureLanguageCard(container) {
    const activeNav = getActiveNavButton(container);
    if (!activeNav || getNavRawKey(activeNav) !== 'Appearance') return;
    const scrollArea = container.querySelector('[data-ag-native-settings-scroll="1"], .w-full.bg-transparent.h-full.overflow-y-auto');
    if (!scrollArea) return;
    const contentWrap = scrollArea.querySelector('.max-w-2xl > div') || scrollArea.querySelector('.max-w-2xl') || scrollArea;
    if (!contentWrap || contentWrap.querySelector('#pm-language-setting-card')) return;

    const card = document.createElement('div');
    card.id = 'pm-language-setting-card';
    card.className = 'pm-language-card pm-no-i18n';
    card.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:12px;">
        <div>
          <div class="pm-card-title-group">
            <span>🌹</span>
            <span class="pm-card-title">界面显示语言 / Display Language</span>
          </div>
          <div class="pm-card-desc">在官方全量汉化文本与原生英文界面之间无损实时切换。</div>
        </div>
      </div>
      <div class="pm-lang-toggle-group">
        <button type="button" class="pm-lang-btn ${curLang === 'zh' ? 'active' : ''}" data-lang="zh">
          <div class="pm-lang-btn-left">
            <span>🇨🇳</span>
            <span class="pm-lang-btn-label">简体中文</span>
          </div>
          <span class="pm-lang-badge">官方汉化</span>
        </button>
        <button type="button" class="pm-lang-btn ${curLang === 'en' ? 'active' : ''}" data-lang="en">
          <div class="pm-lang-btn-left">
            <span>🇬🇧</span>
            <span class="pm-lang-btn-label">English</span>
          </div>
          <span class="pm-lang-badge">Native UI</span>
        </button>
      </div>
    `;
    card.querySelectorAll('.pm-lang-btn').forEach((b) => {
      b.addEventListener('click', (ev) => {
        ev.stopPropagation();
        playSfx('decision');
        syncLangUI(b.getAttribute('data-lang'));
      });
    });

    const firstHeading = contentWrap.querySelector('h2, h3');
    if (firstHeading && firstHeading.nextSibling) {
      contentWrap.insertBefore(card, firstHeading.nextSibling);
    } else {
      contentWrap.prepend(card);
    }
  }

  // --------------------------------------------------------------------------
  // 9. 核心周期扫描 & 仅在模态真正挂载/切页时执行翻译（消除悬停/打字触发整树遍历卡顿!）
  // --------------------------------------------------------------------------
  let syncRaf = 0;
  let lastLangSignature = new WeakMap();
  let scopedModalObserver = null;
  let observedModalRef = null;

  function calcRowTier(count) {
    if (count > 14) return '8';
    if (count > 12) return '7';
    if (count > 10) return '6';
    return '5';
  }

  function syncModalState() {
    syncRaf = 0;
    const enabled = isJrpgEnabled();
    const containers = document.querySelectorAll('.settings-modal-container');
    const backdrops = document.querySelectorAll('.settings-modal-backdrop');

    if (!enabled) {
      document.documentElement.removeAttribute('data-pm-modal-open');
      if (scopedModalObserver) { scopedModalObserver.disconnect(); observedModalRef = null; }
      containers.forEach((c) => {
        c.removeAttribute('data-pm-settings');
        c.removeAttribute('data-pm-scene');
        c.removeAttribute('data-active-detail');
      });
      backdrops.forEach((b) => b.removeAttribute('data-pm-settings'));
      return;
    }

    if (containers.length > 0) {
      document.documentElement.setAttribute('data-pm-modal-open', 'true');
    } else {
      document.documentElement.removeAttribute('data-pm-modal-open');
      if (scopedModalObserver) { scopedModalObserver.disconnect(); observedModalRef = null; }
    }

    backdrops.forEach((b) => {
      b.setAttribute('data-pm-settings', 'enabled');
      if (!b.dataset.pmBackdropBound) {
        b.dataset.pmBackdropBound = '1';
        b.addEventListener('click', (ev) => {
          if (bypassCloseIntercept || ev.target !== b) return;
          const modal = document.querySelector('.settings-modal-container[data-pm-settings="enabled"]');
          if (!modal) return;
          ev.preventDefault();
          ev.stopPropagation();
          closeSettingsModalSmoothly(modal, b, modal.querySelector(':scope > button:first-child'));
        }, true);
      }
    });

    containers.forEach((c) => {
      const justInjected = c.getAttribute('data-pm-injected') !== '1';
      injectModalDecor(c);
      if (justInjected) updateStageScale(c);

      if (observedModalRef !== c) {
        if (scopedModalObserver) scopedModalObserver.disconnect();
        observedModalRef = c;
        scopedModalObserver = new MutationObserver((muts) => {
          for (let i = 0; i < muts.length; i++) {
            const t = muts[i].target;
            if (t && t.closest && t.closest('#pm-char-decor-layer, #pm-help-bar, #pm-sound-btn, #pm-return-btn, #pm-key-hints, #pm-options-frame, #pm-options-bg')) continue;
            if (muts[i].addedNodes && muts[i].addedNodes.length > 0) {
              scheduleSync();
              break;
            }
          }
        });
        scopedModalObserver.observe(c, { childList: true, subtree: true });
      }

      const navBtns = getNavButtons(c);
      navBtns.forEach((nb) => {
        const lbl = (nb.innerText || '').trim();
        if (lbl && nb.title !== lbl) nb.title = lbl;
      });
      c.setAttribute('data-pm-nav-rows', calcRowTier(navBtns.length));
      const countEl = c.querySelector('#pm-chapter-count');
      if (countEl && navBtns.length > 0) {
        const expected = `${navBtns.length} Chapters`;
        if (countEl.textContent !== expected) countEl.textContent = expected;
      }

      if (c.getAttribute('data-pm-scene') === 'menu' && !c.querySelector('.pm-kbd-active')) {
        syncKbdSelection(c, getActiveNavButton(c));
      }

      ensureLanguageCard(c);

      const activeKey = getNavRawKey(getActiveNavButton(c));
      const sig = `${curLang}:${activeKey}:${navBtns.length}`;
      if (lastLangSignature.get(c) !== sig) {
        lastLangSignature.set(c, sig);
        applySafeTextLanguage(c, curLang);
      }
    });
  }

  function scheduleSync() {
    if (syncRaf) return;
    syncRaf = requestAnimationFrame(syncModalState);
  }

  // 外层仅监听直接挂载/卸载模态框的节点（不对 chat/typing 全量子树运行任何解析！）
  const rootWatch = new MutationObserver((mutations) => {
    for (let i = 0; i < mutations.length; i++) {
      const m = mutations[i];
      for (let j = 0; j < m.addedNodes.length; j++) {
        const nd = m.addedNodes[j];
        if (nd.nodeType === 1 && (nd.classList?.contains('settings-modal-container') || nd.classList?.contains('settings-modal-backdrop') || nd.querySelector?.('.settings-modal-container'))) {
          scheduleSync();
          return;
        }
      }
      for (let j = 0; j < m.removedNodes.length; j++) {
        const nd = m.removedNodes[j];
        if (nd.nodeType === 1 && (nd.classList?.contains('settings-modal-container') || nd.classList?.contains('settings-modal-backdrop') || nd.querySelector?.('.settings-modal-container'))) {
          scheduleSync();
          return;
        }
      }
    }
  });
  rootWatch.observe(document.body, { childList: true, subtree: true });
  registerCleanup(() => {
    rootWatch.disconnect();
    if (scopedModalObserver) scopedModalObserver.disconnect();
    if (syncRaf) cancelAnimationFrame(syncRaf);
  });

  // --------------------------------------------------------------------------
  // 10. 全局键盘网格导航 (↑↓←→ / WASD / Z / Enter / X / Esc / Q / E)
  // --------------------------------------------------------------------------
  const onKeyDown = (e) => {
    if (!isJrpgEnabled()) return;
    const modal = document.querySelector('.settings-modal-container[data-pm-settings="enabled"]');
    if (!modal || modal.getAttribute('data-pm-closing') === '1') return;

    // 正在输入框打字或有下拉菜单弹出时，交还原生键盘控制
    const ae = document.activeElement;
    if (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.tagName === 'SELECT' || ae.isContentEditable)) {
      return;
    }
    if (document.querySelector('[role="listbox"], [data-slot="select-content"], [data-select-popup]')) {
      return;
    }

    const scene = modal.getAttribute('data-pm-scene') || 'menu';
    const key = e.key;

    if (scene === 'menu') {
      const navBtns = getNavButtons(modal);
      if (!navBtns.length) return;
      const rows = parseInt(modal.getAttribute('data-pm-nav-rows') || '5', 10) || 5;
      let idx = menuIndexMap.get(modal);
      if (typeof idx !== 'number' || idx < 0 || idx >= navBtns.length) {
        const cur = getActiveNavButton(modal);
        idx = cur ? Math.max(0, navBtns.indexOf(cur)) : 0;
      }

      if (key === 'ArrowDown' || key === 's' || key === 'S') {
        e.preventDefault(); e.stopPropagation();
        idx = (idx + 1) % navBtns.length;
        syncKbdSelection(modal, navBtns[idx]);
        playSfx('cursor');
      } else if (key === 'ArrowUp' || key === 'w' || key === 'W') {
        e.preventDefault(); e.stopPropagation();
        idx = (idx - 1 + navBtns.length) % navBtns.length;
        syncKbdSelection(modal, navBtns[idx]);
        playSfx('cursor');
      } else if (key === 'ArrowRight' || key === 'd' || key === 'D') {
        e.preventDefault(); e.stopPropagation();
        const next = idx + rows < navBtns.length ? idx + rows : idx % rows;
        syncKbdSelection(modal, navBtns[Math.min(next, navBtns.length - 1)]);
        playSfx('cursor');
      } else if (key === 'ArrowLeft' || key === 'a' || key === 'A') {
        e.preventDefault(); e.stopPropagation();
        const next = idx - rows >= 0 ? idx - rows : Math.min(navBtns.length - 1, idx + rows);
        syncKbdSelection(modal, navBtns[next]);
        playSfx('cursor');
      } else if (key === 'Enter' || key === 'z' || key === 'Z') {
        e.preventDefault(); e.stopPropagation();
        if (navBtns[idx]) navBtns[idx].click();
      } else if (key === 'Escape' || key === 'x' || key === 'X') {
        e.preventDefault(); e.stopPropagation();
        closeSettingsModalSmoothly(modal, document.querySelector('.settings-modal-backdrop'), modal.querySelector(':scope > button:first-child'));
      }
      return;
    }

    if (scene === 'settings') {
      if (key === 'Escape' || key === 'x' || key === 'X') {
        e.preventDefault(); e.stopPropagation();
        returnToSceneMenu(modal);
      } else if (key === 'q' || key === 'Q' || key === '[') {
        e.preventDefault(); e.stopPropagation();
        const navBtns = getNavButtons(modal);
        if (!navBtns.length) return;
        const cur = getActiveNavButton(modal);
        const curIdx = cur ? Math.max(0, navBtns.indexOf(cur)) : 0;
        const prevBtn = navBtns[(curIdx - 1 + navBtns.length) % navBtns.length];
        if (prevBtn) prevBtn.click();
      } else if (key === 'e' || key === 'E' || key === ']') {
        e.preventDefault(); e.stopPropagation();
        const navBtns = getNavButtons(modal);
        if (!navBtns.length) return;
        const cur = getActiveNavButton(modal);
        const curIdx = cur ? Math.max(0, navBtns.indexOf(cur)) : 0;
        const nextBtn = navBtns[(curIdx + 1) % navBtns.length];
        if (nextBtn) nextBtn.click();
      }
    }
  };

  window.addEventListener('keydown', onKeyDown, true);
  registerCleanup(() => window.removeEventListener('keydown', onKeyDown, true));

  // 注册热重载清理入口
  function teardown() {
    for (let i = cleanups.length - 1; i >= 0; i--) {
      try { cleanups[i](); } catch (_) {}
    }
    cleanups.length = 0;
    document.documentElement.removeAttribute('data-pm-modal-open');
    document.querySelectorAll('#pm-char-decor-layer, #pm-options-bg, #pm-options-frame, #pm-sound-btn, #pm-return-btn, #pm-key-hints, #pm-tab-prev, #pm-tab-next, #pm-help-bar, #pm-language-setting-card').forEach((el) => {
      try { el.remove(); } catch (_) {}
    });
    document.querySelectorAll('.settings-modal-container').forEach((c) => {
      c.removeAttribute('data-pm-injected');
      c.removeAttribute('data-pm-settings');
      c.removeAttribute('data-pm-scene');
      c.removeAttribute('data-pm-tab-switching');
    });
    if (window.__PM_SETTINGS_TEARDOWN === teardown) {
      delete window.__PM_SETTINGS_TEARDOWN;
    }
  }

  window.__PM_SETTINGS_TEARDOWN = teardown;

  // 启动首帧同步
  syncModalState();
}

// ============================================================================
// 3. 《Pocket Mirror: Goldenertraum》恶魔剧场舞台帷幕 (实时可调参版 v12)
// ============================================================================
function mountPocketMirrorCurtains() {
  if (typeof window === 'undefined' || window.top !== window) return;
  if (typeof window.__PM_CURTAINS_TEARDOWN === 'function') {
    try { window.__PM_CURTAINS_TEARDOWN(); } catch (_) {}
  }

  let overlay = document.getElementById('antigravity-curtain-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'antigravity-curtain-overlay';
    overlay.setAttribute('aria-hidden', 'true');
    document.body.appendChild(overlay);
  }

  let transition = document.getElementById('antigravity-curtain-transition');
  if (!transition) {
    transition = document.createElement('div');
    transition.id = 'antigravity-curtain-transition';
    transition.setAttribute('aria-hidden', 'true');
    transition.innerHTML = `
      <div class="agy-curtain-half-left"></div>
      <div class="agy-curtain-half-right"></div>
      <div class="agy-curtain-frame"></div>
    `;
    document.body.appendChild(transition);
  }

  // 显存预热
  const imgAssets = ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
  imgAssets.forEach(src => {
    const img = new Image();
    img.src = src;
    if (img.decode) img.decode().catch(() => {});
  });

  // 音效预加载
  let sndOpen = null;
  let sndClose = null;
  try {
    sndOpen = new Audio("data:audio/ogg;base64,");
    sndClose = new Audio("data:audio/ogg;base64,");
    sndOpen.volume = 0.65;
    sndClose.volume = 0.65;
    sndOpen.load();
    sndClose.load();
  } catch (e) {
    console.warn('[Curtains] Audio init failed:', e);
  }

  // 侧栏智能避让（rAF 节流，避免高频滑动卡顿）
  let lastInSidebar = false;
  let lastInRight = false;
  let mouseMoveRaf = null;
  function onMouseMove(e) {
    if (mouseMoveRaf) return;
    const clientX = e.clientX;
    const innerWidth = window.innerWidth;
    mouseMoveRaf = requestAnimationFrame(() => {
      mouseMoveRaf = null;
      const inSidebar = clientX <= 360;
      if (inSidebar !== lastInSidebar) {
        lastInSidebar = inSidebar;
        overlay.classList.toggle('hover-sidebar', inSidebar);
      }
      const inRight = clientX >= (innerWidth - 220);
      if (inRight !== lastInRight) {
        lastInRight = inRight;
        overlay.classList.toggle('hover-right', inRight);
      }
    });
  }
  window.addEventListener('mousemove', onMouseMove, { passive: true });

  // ==========================================================================
  // 🎛️ 运行时配置与持久化存储
  // ==========================================================================
  const defaultConfig = {
    closeDuration: 360,
    holdDuration: 40,
    openDuration: 360,
    soundVolume: 65
  };

  let config = Object.assign({}, defaultConfig);
  try {
    const saved = localStorage.getItem('agy_curtain_config');
    if (saved) {
      Object.assign(config, JSON.parse(saved));
    }
  } catch (e) {}

  function applyConfig() {
    document.documentElement.style.setProperty('--curtain-close-dur', (config.closeDuration / 1000) + 's');
    document.documentElement.style.setProperty('--curtain-open-dur', (config.openDuration / 1000) + 's');
    if (sndOpen) sndOpen.volume = config.soundVolume / 100;
    if (sndClose) sndClose.volume = config.soundVolume / 100;
  }
  applyConfig();

  // 核心转场调度函数
  let isTransitioning = false;
  function runTheatreTransition(onCurtainFullyClosed) {
    if (isTransitioning) return;
    isTransitioning = true;

    transition.className = 'active closing';

    if (sndClose && config.soundVolume > 0) {
      try {
        sndClose.currentTime = 0;
        sndClose.play().catch(() => {});
      } catch (_) {}
    }

    setTimeout(() => {
      transition.className = 'active closed-hold';

      if (typeof onCurtainFullyClosed === 'function') {
        try {
          onCurtainFullyClosed();
        } catch (err) {
          console.error('[Curtains] Backend switch error:', err);
        }
      }

      setTimeout(() => {
        if (sndOpen && config.soundVolume > 0) {
          try {
            sndOpen.currentTime = 0;
            sndOpen.play().catch(() => {});
          } catch (_) {}
        }

        transition.className = 'active opening';

        setTimeout(() => {
          transition.className = '';
          isTransitioning = false;
        }, config.openDuration + 30);

      }, config.holdDuration);

    }, config.closeDuration);
  }

  window.__antigravityTriggerCurtainTransition = runTheatreTransition;

  // 侧栏点击拦截与并发转场
  function onSidebarClick(e) {
    const row = e.target.closest(':is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not(button[data-testid="project-header"]):not(button[data-project-card="true"])');
    if (!row) return;

    const isAlreadySelected = row.getAttribute('data-selected') === 'true' ||
                              row.getAttribute('data-active') === 'true' ||
                              row.getAttribute('aria-selected') === 'true';
    if (isAlreadySelected) return;

    runTheatreTransition();
  }
  document.addEventListener('click', onSidebarClick, true);

  // ==========================================================================
  // 🎛️ 挂载实时调参控制台 UI
  // ==========================================================================
  let tuneBtn = document.getElementById('agy-curtain-tune-btn');
  if (!tuneBtn) {
    tuneBtn = document.createElement('div');
    tuneBtn.id = 'agy-curtain-tune-btn';
    tuneBtn.title = '打开恶魔剧场帷幕调参控制台';
    tuneBtn.innerHTML = '🎭';
    document.body.appendChild(tuneBtn);
  }

  let tunePanel = document.getElementById('agy-curtain-tune-panel');
  if (!tunePanel) {
    tunePanel = document.createElement('div');
    tunePanel.id = 'agy-curtain-tune-panel';
    tunePanel.innerHTML = `
      <div class="agy-tune-header">
        <div class="agy-tune-title"><span>🎭</span> 恶魔剧场帷幕实时调参台</div>
        <div class="agy-tune-close" id="agy-tune-close-btn">✕</div>
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>闭幕速度 (Close)</span>
          <span class="agy-tune-val" id="val-close">${config.closeDuration}ms</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-close" min="100" max="1000" step="20" value="${config.closeDuration}">
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>中央停顿 (Hold)</span>
          <span class="agy-tune-val" id="val-hold">${config.holdDuration}ms</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-hold" min="0" max="800" step="20" value="${config.holdDuration}">
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>开幕速度 (Open)</span>
          <span class="agy-tune-val" id="val-open">${config.openDuration}ms</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-open" min="100" max="1000" step="20" value="${config.openDuration}">
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>音效音量 (Volume)</span>
          <span class="agy-tune-val" id="val-vol">${config.soundVolume}%</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-vol" min="0" max="100" step="5" value="${config.soundVolume}">
      </div>

      <div class="agy-tune-presets">
        <button class="agy-tune-preset-btn" id="preset-swift">⚡ 极速流 (200ms)</button>
        <button class="agy-tune-preset-btn" id="preset-golden">✨ 黄金推荐 (360ms)</button>
        <button class="agy-tune-preset-btn" id="preset-classic">🎪 原版40帧 (670ms)</button>
        <button class="agy-tune-preset-btn" id="preset-rebound">🪞 触碰即开 (0ms停顿)</button>
      </div>

      <div class="agy-tune-actions" style="margin-bottom:8px;">
        <button class="agy-tune-action-btn" id="agy-btn-toggle-jrpg" style="background:rgba(212,175,55,0.12);border:1px solid rgba(212,175,55,0.45);color:#ffd700;">🎮 JRPG设置: 加载中</button>
        <button class="agy-tune-action-btn" id="agy-btn-toggle-skin-off" style="background:rgba(60,40,50,0.65);border:1px solid rgba(212,175,55,0.45);color:#f7f1e5;">🪞 关闭化妆镜皮肤</button>
      </div>

      <div class="agy-tune-actions">
        <button class="agy-tune-action-btn agy-btn-test" id="agy-btn-run-test">▶ 一键测试播放</button>
      </div>
    `;
    document.body.appendChild(tunePanel);
  }

  // 事件绑定
  tuneBtn.onclick = () => {
    tunePanel.classList.toggle('visible');
  };
  document.getElementById('agy-tune-close-btn').onclick = () => {
    tunePanel.classList.remove('visible');
  };

  const sClose = document.getElementById('slider-close');
  const sHold = document.getElementById('slider-hold');
  const sOpen = document.getElementById('slider-open');
  const sVol = document.getElementById('slider-vol');

  function saveConfig() {
    try {
      localStorage.setItem('agy_curtain_config', JSON.stringify(config));
    } catch (e) {}
  }

  sClose.oninput = (e) => {
    config.closeDuration = parseInt(e.target.value);
    document.getElementById('val-close').innerText = config.closeDuration + 'ms';
    applyConfig();
    saveConfig();
  };

  sHold.oninput = (e) => {
    config.holdDuration = parseInt(e.target.value);
    document.getElementById('val-hold').innerText = config.holdDuration + 'ms';
    applyConfig();
    saveConfig();
  };

  sOpen.oninput = (e) => {
    config.openDuration = parseInt(e.target.value);
    document.getElementById('val-open').innerText = config.openDuration + 'ms';
    applyConfig();
    saveConfig();
  };

  sVol.oninput = (e) => {
    config.soundVolume = parseInt(e.target.value);
    document.getElementById('val-vol').innerText = config.soundVolume + '%';
    applyConfig();
    saveConfig();
  };

  // 预设按钮
  function setPreset(cDur, hDur, oDur) {
    config.closeDuration = cDur;
    config.holdDuration = hDur;
    config.openDuration = oDur;
    sClose.value = cDur;
    sHold.value = hDur;
    sOpen.value = oDur;
    document.getElementById('val-close').innerText = cDur + 'ms';
    document.getElementById('val-hold').innerText = hDur + 'ms';
    document.getElementById('val-open').innerText = oDur + 'ms';
    applyConfig();
    saveConfig();
    runTheatreTransition();
  }

  document.getElementById('preset-swift').onclick = () => setPreset(200, 0, 200);
  document.getElementById('preset-golden').onclick = () => setPreset(360, 40, 360);
  document.getElementById('preset-classic').onclick = () => setPreset(670, 200, 670);
  document.getElementById('preset-rebound').onclick = () => setPreset(320, 0, 320);

  // 一键试运行
  document.getElementById('agy-btn-run-test').onclick = () => {
    runTheatreTransition();
  };

  // JRPG 设置菜单独立开关
  const jrpgToggleBtn = document.getElementById('agy-btn-toggle-jrpg');
  function syncJrpgBtnLabel() {
    if (!jrpgToggleBtn) return;
    let disabled = false;
    try { disabled = localStorage.getItem('pm-disable-jrpg-settings') === 'true'; } catch (_) {}
    if (!disabled && window.__PM_DISABLE_JRPG_SETTINGS === true) disabled = true;
    try {
      const cfg = window.__AG_PATCH_CTX__?.config;
      if (cfg && cfg.modules && cfg.modules.jrpgSettings === false) disabled = true;
    } catch (_) {}
    jrpgToggleBtn.textContent = disabled ? '🎮 JRPG设置: 关' : '🎮 JRPG设置: 开';
  }
  syncJrpgBtnLabel();
  if (jrpgToggleBtn) {
    jrpgToggleBtn.onclick = () => {
      let wasDisabled = false;
      try { wasDisabled = localStorage.getItem('pm-disable-jrpg-settings') === 'true'; } catch (_) {}
      const nextDisabled = !wasDisabled;
      try { localStorage.setItem('pm-disable-jrpg-settings', nextDisabled ? 'true' : 'false'); } catch (_) {}
      if (nextDisabled) {
        if (typeof window.__PM_SETTINGS_TEARDOWN === 'function') {
          try { window.__PM_SETTINGS_TEARDOWN(); } catch (_) {}
        }
      } else {
        mountPocketMirrorSettings();
      }
      syncJrpgBtnLabel();
      if (typeof window.__PM_SKIN_CONTROLLER__?.showToast === 'function') {
        window.__PM_SKIN_CONTROLLER__.showToast(nextDisabled ? '🎮 JRPG 设置菜单已关闭（已恢复原生设置）' : '🎮 JRPG 设置菜单已开启');
      }
    };
  }

  // 在调参面板中一键关闭整套化妆镜皮肤
  const skinOffBtn = document.getElementById('agy-btn-toggle-skin-off');
  if (skinOffBtn) {
    skinOffBtn.onclick = () => {
      if (typeof window.__PM_SKIN_CONTROLLER__?.setEnabled === 'function') {
        window.__PM_SKIN_CONTROLLER__.setEnabled(false);
      }
    };
  }

  function teardownCurtains() {
    if (mouseMoveRaf) {
      cancelAnimationFrame(mouseMoveRaf);
      mouseMoveRaf = null;
    }
    window.removeEventListener('mousemove', onMouseMove);
    document.removeEventListener('click', onSidebarClick, true);
    if (window.__antigravityTriggerCurtainTransition === runTheatreTransition) {
      delete window.__antigravityTriggerCurtainTransition;
    }
    if (overlay) overlay.remove();
    if (transition) transition.remove();
    if (tuneBtn) tuneBtn.remove();
    if (tunePanel) tunePanel.remove();
    if (window.__PM_CURTAINS_TEARDOWN === teardownCurtains) {
      delete window.__PM_CURTAINS_TEARDOWN;
    }
  }

  window.__PM_CURTAINS_TEARDOWN = teardownCurtains;
  console.log('[Curtains] Live Tuning Console v12 mounted!');
}

// ============================================================================
